struct RGB {
    double r, g, b;   // valeurs dans [0, 1]
};

// H en degrés [0, 360), S et I dans [0, 1]
cPt3dr Claude_hsiToRgb(double h, double s, double i)
{
    const double PI = 3.14159265358979323846;
    const double deg2rad = PI / 180.0;

    // Normaliser la teinte dans [0, 360)
    h = std::fmod(h, 360.0);
    if (h < 0) h += 360.0;

    s = std::clamp(s, 0.0, 1.0);
    i = std::clamp(i, 0.0, 1.0);

    double r, g, b;

    auto f = [&](double hh) {
        // I * (1 + S*cos(H) / cos(60° - H))
        return i * (1.0 + s * std::cos(hh * deg2rad) / std::cos((60.0 - hh) * deg2rad));
    };

    if (h < 120.0) {                 // secteur RG
        b = i * (1.0 - s);
        r = f(h);
        g = 3.0 * i - (r + b);
    } else if (h < 240.0) {          // secteur GB
        h -= 120.0;
        r = i * (1.0 - s);
        g = f(h);
        b = 3.0 * i - (r + g);
    } else {                         // secteur BR
        h -= 240.0;
        g = i * (1.0 - s);
        b = f(h);
        r = 3.0 * i - (g + b);
    }

    // Écrêtage pour éviter les débordements numériques
    return { std::clamp(r, 0.0, 1.0),
             std::clamp(g, 0.0, 1.0),
             std::clamp(b, 0.0, 1.0) };
}


cPt3dr Claude_rgbToHsi(double r, double g, double b)
{
    const double PI = 3.14159265358979323846;
    const double rad2deg = 180.0 / PI;
    const double eps = 1e-12;

    r = std::clamp(r, 0.0, 1.0);
    g = std::clamp(g, 0.0, 1.0);
    b = std::clamp(b, 0.0, 1.0);

    double i = (r + g + b) / 3.0;
    double mn = std::min({r, g, b});

    // Noir : S et H indéfinis
    if (i < eps) return {0.0, 0.0, 0.0};

    double s = 1.0 - mn / i;

    // Gris (R = G = B) : H indéfini
    double num = 0.5 * ((r - g) + (r - b));
    double den = std::sqrt((r - g) * (r - g) + (r - b) * (g - b));
    if (den < eps) return {0.0, 0.0, i};

    double h = std::acos(std::clamp(num / den, -1.0, 1.0)) * rad2deg;
    if (b > g) h = 360.0 - h;

    return {h, s, i};
}






struct Lab { double L, a, b; };   // L in [0,100]
struct RGB8 { uint8_t r, g, b; };

// Blanc de référence D65 (Y = 1)
constexpr double Xn = 0.95047;
constexpr double Yn = 1.00000;
constexpr double Zn = 1.08883;

// Inverse de la fonction f de Lab
static double LabFInv(double t)
{
    constexpr double delta = 6.0 / 29.0;
    if (t > delta)
        return t * t * t;
    return 3.0 * delta * delta * (t - 4.0 / 29.0);
}

// Correction gamma sRGB (linéaire -> non linéaire)
static double LinearToSRGB(double c)
{
    if (c <= 0.0031308)
        return 12.92 * c;
    return 1.055 * std::pow(c, 1.0 / 2.4) - 0.055;
}

static std::array<double, 3> LabToXYZ(const Lab& lab)
{
    const double fy = (lab.L + 16.0) / 116.0;
    const double fx = fy + lab.a / 500.0;
    const double fz = fy - lab.b / 200.0;
    return { Xn * LabFInv(fx), Yn * LabFInv(fy), Zn * LabFInv(fz) };
}

static std::array<double, 3> XYZToLinearRGB(const std::array<double, 3>& xyz)
{
    const double X = xyz[0], Y = xyz[1], Z = xyz[2];
    return {
         3.2404542 * X - 1.5371385 * Y - 0.4985314 * Z,
        -0.9692660 * X + 1.8760108 * Y + 0.0415560 * Z,
         0.0556434 * X - 0.2040259 * Y + 1.0572252 * Z
    };
}

// Conversion Lab -> sRGB en [0,1] (clampé : les couleurs hors gamut sont tronquées)
std::array<double, 3> LabToRGB(const Lab& lab)
{
    auto lin = XYZToLinearRGB(LabToXYZ(lab));
    std::array<double, 3> rgb;
    for (int i = 0; i < 3; ++i)
    {
        double c = std::clamp(lin[i], 0.0, 1.0);
        rgb[i] = LinearToSRGB(c);
    }
    return rgb;
}

RGB8 LabToRGB8(const Lab& lab)
{
    auto rgb = LabToRGB(lab);
    auto to8 = [](double v) { return static_cast<uint8_t>(std::lround(v * 255.0)); };
    return { to8(rgb[0]), to8(rgb[1]), to8(rgb[2]) };
}

void LAB_main()
{
    const Lab tests[] = {
        {100, 0, 0},        // blanc
        {0, 0, 0},          // noir
        {53.24, 80.09, 67.20},   // rouge
        {87.73, -86.18, 83.18},  // vert
        {32.30, 79.19, -107.86}  // bleu
    };
    for (const auto& lab : tests)
    {
        RGB8 c = LabToRGB8(lab);
        std::cout << "Lab(" << lab.L << ", " << lab.a << ", " << lab.b << ") -> RGB("
                  << int(c.r) << ", " << int(c.g) << ", " << int(c.b) << ")\n";
    }
}



